1	`include "elink_regmap.vh"
2	module erx_arbiter (/*AUTOARG*/
3	   // Outputs
4	   rx_rd_wait, rx_wr_wait, edma_wait, ecfg_wait, rxwr_access,
5	   rxwr_packet, rxrd_access, rxrd_packet, rxrr_access, rxrr_packet,
6	   // Inputs
7	   erx_access, erx_packet, mailbox_wait, edma_access, edma_packet,
