9	   );
10	
11	   parameter AW   = 32;
12	   parameter DW   = 32;
13	   parameter PW   = 104;
14	   parameter ID   = 12'h800; //link id
15	   parameter RFAW = 6;
16	   
17	   //Incoming packet (writes)  
18	   input           erx_access; //from MMU
19	   input [PW-1:0]  erx_packet;
20	   output          rx_rd_wait; //for IO
21	   output          rx_wr_wait; //for IO
