40	   
41	   //To Master Read FIFO
42	   output 	   rxrd_access;
43	   output [PW-1:0] rxrd_packet;   
44	   input           rxrd_wait;
45	   
46	   //To Slave Read Response FIFO
47	   output 	   rxrr_access;
48	   output [PW-1:0] rxrr_packet;   
49	   input           rxrr_wait;
50	
51	   //####################################
52	   //Splicing pakets
53	   //####################################
54	   wire 	   erx_write;
55	   wire [AW-1:0]   erx_dstaddr;
56	   wire 	   erx_read;
57	   
58	   packet2emesh #(.AW(AW))
59	   p2e (// Outputs
60		.write_in	(erx_write),
61		.datamode_in	(),
62		.ctrlmode_in	(),
63		.data_in	(),
