96	   
97	   assign rxrd_access         = erx_read | edma_access;
98	   
99	   assign rxrd_packet[PW-1:0] = erx_read ? erx_packet[PW-1:0] : 
100					            edma_packet[PW-1:0];
101	   
102	   //####################################
103	   //Wait Signals
104	   //####################################   
105	   assign ecfg_wait     = rxrr_wait;
106	
107	   assign edma_wait     = rxrd_wait | erx_read;
108	   
109	   assign rx_rd_wait    = rxrd_wait;
110	
111	   assign rx_wr_wait    = ecfg_access  |
